#!/usr/bin/env bash
# step43 — Home "Orders delivered" counter: base 50,000 (or admin's higher value),
# grows steadily over time + live on-page ticker.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step43-$TS
MD5="326bb1800fcba7059a248168cec15238"
mkdir -p "$BAK/views"
cp "$APP/views/home.ejs" "$BAK/views/home.ejs"
restore(){ echo "!! rollback"; cp "$BAK/views/home.ejs" "$APP/views/home.ejs"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
echo "==> write home.ejs"
cat > /tmp/s43_home.b64 <<'B64H'

B64H
base64 -d /tmp/s43_home.b64 > "$APP/views/home.ejs"; rm -f /tmp/s43_home.b64
G=$(md5sum "$APP/views/home.ejs"|awk '{print $1}'); echo "   md5 $G (expect $MD5)"
[ "$G" = "$MD5" ] || { echo "!! md5 mismatch"; false; }
echo "==> ejs compile"
node -e 'const ejs=require("/opt/gsz/node_modules/ejs"),fs=require("fs");ejs.compile(fs.readFileSync("/opt/gsz/views/home.ejs","utf8"),{filename:"/opt/gsz/views/home.ejs"});console.log("   OK");'
echo "==> pm2 restart"; pm2 restart gsz --update-env >/dev/null; sleep 3
H=$(curl -s -m 15 http://127.0.0.1:3900/ || true)
grep -q '</html>' <<<"$H" || { echo "!! home broken"; false; }
grep -q 'id="odNum"' <<<"$H" || { echo "!! counter element missing"; false; }
grep -q 'Orders delivered' <<<"$H" || { echo "!! orders label missing"; false; }
DC=$(grep -oE 'id="odNum" data-count="[0-9]+"' <<<"$H" | grep -oE '[0-9]+' | head -1)
echo "   data-count = $DC"
[ -n "$DC" ] && [ "$DC" -ge 50000 ] || { echo "!! counter not >= 50000"; false; }
trap - ERR
echo "==> step43 OK — orders counter from $DC. Backup: $BAK"
